var maxProfit = function(prices) {
    let minPrice = Infinity;
    let maxProfit = 0;
    for (let i = 0; i < prices.length; i++) {
        const p = prices[i];
        if (p < minPrice) {
            minPrice = p;
        } else if (p - minPrice > maxProfit) {
            maxProfit = p - minPrice;
        }
    }
    return maxProfit;
};
